@startuml

class City {
  +name : string
  +inhabitants : int
}

class Attraction {
  +name : string
  +address : string
}

class GuidedTour {
  +duration : int
  +number : int
}

class Discount {
  +amount : float
}

class Person {
  +name : string
}

class Visitor extends Person {}

class Guide extends Person {}

City "1" -- "*" Attraction
Attraction "1" -- "*" GuidedTour
GuidedTour "1" -- "1" Guide
GuidedTour "1" -- "0..20" Visitor
Visitor "1" -- "*" Discount
Discount "1" -- "1" GuidedTour

@enduml

